L13_1.m_Pos = "L"
L13_1.m_Talk_KOREA = "어머니는 제가 태어나기 전부터 이런 침식체들과 맞서왔대요."
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "お母さんは、私が生まれる前から侵食体と戦ってきたんですって。"
L13_1.m_Talk_ENG = "Mother said that she fought those kinds of C.O.s since before I was born."
L13_1.m_Talk_TWN = "媽媽在我出生之前就一直在與這些侵蝕體作戰。"
L13_1.m_Talk_SCN = "母亲在我出生之前就一直在与这些侵蚀体作战。"
L13_1.m_Talk_DEU = "Mother said that she fought those kinds of C.O.s since before I was born."
L13_1.m_Talk_FRA = "Mother said that she fought those kinds of C.O.s since before I was born."
L14_1 = {}
L14_1.m_CutScenKey_Talk = "EP12_ACT3_STAGE2_END@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 558
L14_1.m_CutScenStrID = "EP12_ACT3_STAGE2_END"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_CharStrID = "SOLOVEY_ADMIN_NULL_NULL"
L14_1.m_Pos = "L"
L14_1.m_Talk_KOREA = "제 키보다 백 배는 더 큰 침식체도 있는데, 그게 정원의 가장 깊은 안뜰에 있다고 했어요."
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "私より百倍は背が高い侵食体も存在して、それは庭園の一番奥の庭にいるそうです。"
L14_1.m_Talk_ENG = "There are even C.O.s that are a hundred times bigger than me, and they live in the deepest part of the garden's inner yard."
L14_1.m_Talk_TWN = "有比我高一百倍的侵蝕體，據說它就在花園最深處的內院。"
L14_1.m_Talk_SCN = "有比我高一百倍的侵蚀体，据说它就在花园最深处的内院。"
L14_1.m_Talk_DEU = "There are even C.O.s that are a hundred times bigger than me, and they live in the deepest part of the garden's inner yard."
L14_1.m_Talk_FRA = "There are even C.O.s that are a hundred times bigger than me, and they live in the deepest part of the garden's inner yard."
