L16_1 = {}
L16_1.m_CutScenKey_Talk = "EP12_ACT3_STAGE2_END@16#Talk"
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 558
L16_1.m_CutScenStrID = "EP12_ACT3_STAGE2_END"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_LAUGH"
L16_1.m_CharStrID = "SOLOVEY_ADMIN_NULL_NULL"
L16_1.m_Pos = "L"
L16_1.m_Talk_KOREA = "그래서 어머니 혼자 정원 안뜰로 떠나신 거예요. 싸워본 적 없는 절 대신해 침식체들을 막기 위해서요."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "だからお母さんは1人で中庭に向かったんです。まだ戦った経験のない私のために、侵食体を阻止するために。"
L16_1.m_Talk_ENG = "That's why Mother left for the garden's inner yard by herself. To stop the C.O.s instead of me."
L16_1.m_Talk_TWN = "所以媽媽才一個人去了花園。為了替代從未戰鬥過的我阻擋侵蝕體。"
L16_1.m_Talk_SCN = "所以母亲才一个人去了花园。为了替代从未战斗过的我阻挡侵蚀体。"
L16_1.m_Talk_DEU = "That's why Mother left for the garden's inner yard by herself. To stop the C.O.s instead of me."
L16_1.m_Talk_FRA = "That's why Mother left for the garden's inner yard by herself. To stop the C.O.s instead of me."
L17_1 = {}
L17_1.m_CutScenKey_Talk = "EP12_ACT3_STAGE2_END@17#Talk"
L17_1.m_CutScenProcessKey = 17
L17_1.m_CutScenID = 558
L17_1.m_CutScenStrID = "EP12_ACT3_STAGE2_END"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_IDLE"
L17_1.m_CharStrID = "SOLOVEY_ADMIN_NULL_NULL"
L17_1.m_Pos = "L"
L17_1.m_Talk_KOREA = "어머니 말씀대로라면 저희는 깊이 들어갈수록 더 강한 괴물과 마주치게 되겠죠."
L17_1.m_fTalkTime = 0.03
L17_1.m_Talk_JPN = "お母さんの話どおりなら、奥に行くほど強い化け物に遭遇することになるでしょう。"
L17_1.m_Talk_ENG = "According to Mother's words, the deeper we go in, the stronger the C.O.s we'll encounter."
L17_1.m_Talk_TWN = "按照媽媽所說，我們越深入就會遇到越強的怪物。"
L17_1.m_Talk_SCN = "按照母亲所说，我们越深入就会遇到越强的怪物。"
L17_1.m_Talk_DEU = "According to Mother's words, the deeper we go in, the stronger the C.O.s we'll encounter."
L17_1.m_Talk_FRA = "According to Mother's words, the deeper we go in, the stronger the C.O.s we'll encounter."
L18_1 = {}
L18_1.m_CutScenKey_Talk = "EP12_ACT3_STAGE2_END@18#Talk"
L18_1.m_CutScenProcessKey = 18
L18_1.m_CutScenID = 558
L18_1.m_CutScenStrID = "EP12_ACT3_STAGE2_END"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_CharStrID = "SOLOVEY_ADMIN_NULL_NULL"
L18_1.m_Pos = "L"
L18_1.m_Talk_KOREA = "도망치면서 안전한 길만 찾다보면, 평생이 걸려도 어머닐 만나지 못할 것 같았어요."
L18_1.m_fTalkTime = 0.03
L18_1.m_Talk_JPN = "逃げながら安全な道ばかり探していたら、一生かけてもお母さんに会えない気がするんです。"
L18_1.m_Talk_ENG = "So, I felt like we would never see her if we were to flee and try to look for a safe passageway."
L18_1.m_Talk_TWN = "如果一直逃跑的話，我覺得一輩子也不會見到她了。"
L18_1.m_Talk_SCN = "如果一直逃跑的话，我觉得一辈子也不会见到她了。"
L18_1.m_Talk_DEU = "So, I felt like we would never see her if we were to flee and try to look for a safe passageway."
L18_1.m_Talk_FRA = "So, I felt like we would never see her if we were to flee and try to look for a safe passageway."
