L27_1.m_Pos = "C"
L27_1.m_Talk_KOREA = "네가 무리하다 다치면 파블린이 슬퍼할 테니까."
L27_1.m_fTalkTime = 0.03
L27_1.m_Talk_JPN = "ただ、あなたが無理をして怪我でもしたら、パブリンが悲しむから。"
L27_1.m_Talk_ENG = "I'm just saying, Pavlin would be sad if you get hurt while being reckless."
