L27_1.m_Talk_SCN = "你要是逞强受伤了，难过的会是帕芙琳。"
L27_1.m_Talk_DEU = "I'm just saying, Pavlin would be sad if you get hurt while being reckless."
L27_1.m_Talk_FRA = "I'm just saying, Pavlin would be sad if you get hurt while being reckless."
