L16_1 = "과거의 기억일 거다. 우리가 찾으려는 보물에서 흘러나온 거지."
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "過去の記憶だね。私たちが探しているお宝から流れてきたんだ。"
L15_1.m_Talk_JPN = L16_1
L16_1 = "It's a memory of the past. It's coming from the treasure we're after."
L15_1.m_Talk_ENG = L16_1
L16_1 = "那些應該是過去的記憶。從我們要找的寶物裡散發出來的。"
L15_1.m_Talk_TWN = L16_1
L16_1 = "那些应该是过去的记忆。从我们要找的宝物里逸散出来的。"
