L17_1 = "정원 중심의 봉인에 가까워지면서, 그곳에 보관된 기억의 일부를 보게 된 거야."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "庭園の中心にある封印に近づいたことで、そこに保管された記憶の一部を覗いたんだよ。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "As we get closer to the seal at the center of the garden, we're able to get glimpses of the memories stored in it."
L16_1.m_Talk_ENG = L17_1
L17_1 = "隨著接近花園中心的封印，我們能夠看到保存在那裡的一部分記憶。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "随着接近花园中心的封印，我们能够看到保存在那里的一部分记忆。"
