L28_1 = "한 사람을 너무 오랫동안 알고 지내다 보면, 그 사람의 좋은 면만 볼 수가 없거든."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "付き合いが長ければ長いほど、悪いころも目に入るんだよ。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "Because, once you get to know someone for a long time, you can't only see their good side."
L27_1.m_Talk_ENG = L28_1
L28_1 = "一個人如果認識太久，就無法只看到他好的一面。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "一个人如果认识太久，就无法只看到他好的一面。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "Because, once you get to know someone for a long time, you can't only see their good side."
L27_1.m_Talk_DEU = L28_1
L28_1 = "Because, once you get to know someone for a long time, you can't only see their good side."
L27_1.m_Talk_FRA = L28_1
