L28_1.m_fTalkTime = 0.03
L29_1 = "逆に言えば、第一印象が悪かった人でも仲良くなれるってこと。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "In other words, just because your first impression to someone was bad, that doesn't mean that you lost your chance to become friends."
L28_1.m_Talk_ENG = L29_1
L29_1 = "換句話說，第一印象不好並不就表示一輩子都沒有機會變熟。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "换句话说，第一印象不好并不意味着一辈子都没有机会亲近。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "In other words, just because your first impression to someone was bad, that doesn't mean that you lost your chance to become friends."
L28_1.m_Talk_DEU = L29_1
L29_1 = "In other words, just because your first impression to someone was bad, that doesn't mean that you lost your chance to become friends."
