L7_1 = "아, 그러고 보니 패리는 어떤 기억을 봤어요? 저랑 똑같은 기억인가요?"
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "あ、そういえばパリーはどんな記憶を見たんですか？　私と同じ記憶？"
