L21_1.m_CharStrID = L22_1
L21_1.m_Pos = "C"
L22_1 = "네 녀석이 카운터가 된 게 엊그제도 아니고, 이제 와서 그런 게 궁금해진 거냐?"
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "お前がカウンターになったのは昨日や今日のことじゃないだろう。今更そんなことが気になるのか？"
L21_1.m_Talk_JPN = L22_1
L22_1 = "You've been a Counter for a long time. Why are you suddenly curious about that?"
L21_1.m_Talk_ENG = L22_1
L22_1 = "你成為制裁者也不是一天兩天的事了，現在才開始好奇這些嗎？"
L21_1.m_Talk_TWN = L22_1
L22_1 = "你成为制裁者也不是一天两天的事了，现在才开始好奇这些吗？"
