L24_1 = "MOM_NPC_BIRDCAGE_NULL"
L23_1.m_CharStrID = L24_1
L24_1 = "헤헤, 카운터는 세상에 침식체라는 괴물들이 나타났을 때 함께 생겨난 개념이잖아요."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "えへへ、カウンターは、侵食体という化け物がこの世界に現れた時、一緒に生まれた概念でしょう？"
L23_1.m_Talk_JPN = L24_1
L24_1 = "Hehe, because Counter is a concept that arose when monsters called C.O.s started to appear around the world."
L23_1.m_Talk_ENG = L24_1
L24_1 = "嘿嘿，制裁者這個概念，不是在世界上出現侵蝕體這種怪物的時候才一起誕生的嗎？"
L23_1.m_Talk_TWN = L24_1
L24_1 = "嘿嘿，制裁者这个概念不是在世界上出现侵蚀体这种怪物的时候才一起诞生的吗？"
L23_1.m_Talk_SCN = L24_1
L24_1 = "Hehe, because Counter is a concept that arose when monsters called C.O.s started to appear around the world."
L23_1.m_Talk_DEU = L24_1
L24_1 = "Hehe, because Counter is a concept that arose when monsters called C.O.s started to appear around the world."
L23_1.m_Talk_FRA = L24_1
