L25_1 = "MOM_NPC_BIRDCAGE_NULL"
L24_1.m_CharStrID = L25_1
L25_1 = "그래서 관리국이 알려지지 않았던 시절엔… 괴물들이랑 다름없는 취급을 받기도 했고요."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "だからまだ管理局が知られてなかった頃は……カウンターも化け物と同じ扱いをされたこともありましたね。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "That's why when the Administration was not well known... Counters were the ones that were treated like monsters."
L24_1.m_Talk_ENG = L25_1
L25_1 = "所以在管理局還不為人知的時候……我們也曾被當成怪物一樣對待。"
L24_1.m_Talk_TWN = L25_1
L25_1 = "所以在管理局还不为人知的时候……我们也曾被当成怪物一样对待。"
L24_1.m_Talk_SCN = L25_1
L25_1 = "That's why when the Administration was not well known... Counters were the ones that were treated like monsters."
L24_1.m_Talk_DEU = L25_1
L25_1 = "That's why when the Administration was not well known... Counters were the ones that were treated like monsters."
