L28_1 = "MOM_NPC_BIRDCAGE_NULL"
L27_1.m_CharStrID = L28_1
L28_1 = "전 말이죠. 어둠이 있어야 빛이 있는 것처럼, 카운터도 그런 존재라고 생각하거든요."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "闇があってこそ光が存在する。私はカウンターも同じだと思います。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "For me, I think the term Counter exists the same way–where there is darkness, there must be light."
L27_1.m_Talk_ENG = L28_1
L28_1 = "我覺得啊，就像有黑暗才有光明一樣，制裁者也是這樣的存在。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "我觉得啊，就像有黑暗才有光明一样，制裁者也是这样的存在。"
L27_1.m_Talk_SCN = L28_1
L28_1 = "For me, I think the term Counter exists the same way–where there is darkness, there must be light."
L27_1.m_Talk_DEU = L28_1
L28_1 = "For me, I think the term Counter exists the same way–where there is darkness, there must be light."
L27_1.m_Talk_FRA = L28_1
