L29_1 = "EP12_ACT3_STAGE2_END@228#Talk"
L28_1.m_CutScenKey_Talk = L29_1
L29_1 = 228
L28_1.m_CutScenProcessKey = L29_1
L28_1.m_CutScenID = 558
L28_1.m_CutScenStrID = "EP12_ACT3_STAGE2_END"
L28_1.m_bWaitClick = true
L28_1.m_fWaitTime = 0
L29_1 = "MOM_NPC_BIRDCAGE_NULL"
L28_1.m_CharStrID = L29_1
L29_1 = "침식체라는 절망이 우리 세계에 나타났으니, 그에 맞설 희망으로서 카운터가 생겨나는 거죠."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "侵食体という絶望が私たちの世界に現れて、それに立ち向かう希望としてカウンターが生まれたんだと。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "Since the despair of C.O.s appeared in our world, we created the term Counter as a hope to fight against it."
L28_1.m_Talk_ENG = L29_1
L29_1 = "既然會有侵蝕體這種令人絕望的東西出現在我們世界，那麼制裁者就作為希望誕生了。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "既然会有侵蚀体这种令人绝望的东西出现在我们世界，那么制裁者就作为希望诞生了。"
L28_1.m_Talk_SCN = L29_1
L29_1 = "Since the despair of C.O.s appeared in our world, we created the term Counter as a hope to fight against it."
L28_1.m_Talk_DEU = L29_1
L29_1 = "Since the despair of C.O.s appeared in our world, we created the term Counter as a hope to fight against it."
L28_1.m_Talk_FRA = L29_1
