L31_1 = "HILDE_FENRIR_ADMIN_PAST"
L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "C"
L31_1 = "카운터는 침식이라는 병원균에 저항하기 위해 세계가 만들어낸 항체 같은 거야."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "カウンターは、侵食という病原体に抵抗するために世界が生み出した抗体のようなものだ。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Counters are like antibodies created by the world to rid the world of the bacteria called Corruption."
L30_1.m_Talk_ENG = L31_1
L31_1 = "制裁者是為了抵抗侵蝕這種病原體，而由世界所創造出的抗體。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "但简单来说，制裁者是为了抵抗侵蚀这种病原体而由世界所创造出的抗体。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Counters are like antibodies created by the world to rid the world of the bacteria called Corruption."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Counters are like antibodies created by the world to rid the world of the bacteria called Corruption."
L30_1.m_Talk_FRA = L31_1
