L31_1.m_CharStrID = L32_1
L31_1.m_Pos = "C"
L32_1 = "그리고 대적자인 넌, 마왕이란 새로운 질병에 대응하기 위해 만들어진 유일한 백신이지."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "そして敵対者のお前は、魔王という新しい病に対応するために生まれた唯一のワクチンと言える。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "And you, the Antagonist, are the sole vaccine that can fight the new disease we call the Demon Lord."
L31_1.m_Talk_ENG = L32_1
L32_1 = "而你，作為敵對者，則是為了應對魔王這一新疾病而製造的唯一疫苗。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "而你，作为敌对者，则是为了应对魔王这一新疾病而制造的唯一疫苗。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "And you, the Antagonist, are the sole vaccine that can fight the new disease we call the Demon Lord."
L31_1.m_Talk_DEU = L32_1
L32_1 = "And you, the Antagonist, are the sole vaccine that can fight the new disease we call the Demon Lord."
